def countSequences(n: int, m: int, k: int) -> int:
    MOD = 1_000_000_007
    if k < n or k > n * m:
        return 0
    dp = [0] * (k + 1)
    dp[0] = 1
    for step in range(1, n + 1):
        next_dp = [0] * (k + 1)
        for s in range(step, min(k, step * m) + 1):
            val = 0
            for x in range(1, min(m, s) + 1):
                val = (val + dp[s - x]) % MOD
            next_dp[s] = val
        dp = next_dp
    return dp[k]

#include <vector>
#include <algorithm>

class Solution {
public:
    int countSequences(int n, int m, int k) {
        const int MOD = 1e9 + 7;
        if (k < n || k > n * m) return 0;
        std::vector<int> dp(k + 1, 0);
        dp[0] = 1;
        for (int step = 1; step <= n; ++step) {
            std::vector<int> next_dp(k + 1, 0);
            for (int s = step; s <= std::min(k, step * m); ++s) {
                long long val = 0;
                for (int x = 1; x <= std::min(m, s); ++x) {
                    val = (val + dp[s - x]) % MOD;
                }
                next_dp[s] = val;
            }
            dp = std::move(next_dp);
        }
        return dp[k];
    }
};

class Solution {
    public int countSequences(int n, int m, int k) {
        int MOD = 1_000_000_007;
        if (k < n || (long)n * m < k) return 0;
        int[] dp = new int[k + 1];
        dp[0] = 1;
        for (int step = 1; step <= n; step++) {
            int[] nextDp = new int[k + 1];
            for (int s = step; s <= Math.min(k, step * m); s++) {
                long val = 0;
                for (int x = 1; x <= Math.min(m, s); x++) {
                    val = (val + dp[s - x]) % MOD;
                }
                nextDp[s] = (int) val;
            }
            dp = nextDp;
        }
        return dp[k];
    }
}

